class FiatStablecoin:
    """Stablecoin fiat-backed: il custode tiene i dollari, il contratto i saldi."""
    def __init__(self):
        self.balances = {}
        self.reserve_usd = 0      # dollari nel conto del custode (off-chain)

    def total_supply(self):
        return sum(self.balances.values())

    def deposit_and_mint(self, user, usd):
        self.reserve_usd += usd
        self.balances[user] = self.balances.get(user, 0) + usd

    def transfer(self, frm, to, amount):
        if self.balances.get(frm, 0) < amount:
            raise ValueError("saldo insufficiente")
        self.balances[frm] -= amount
        self.balances[to] = self.balances.get(to, 0) + amount

    def burn_and_withdraw(self, user, usd):
        if self.balances.get(user, 0) < usd:
            raise ValueError("saldo insufficiente")
        self.balances[user] -= usd
        self.reserve_usd -= usd

    def check(self, label):
        ok = self.total_supply() == self.reserve_usd
        print(f"{label:10s} saldi={self.balances} riserva={self.reserve_usd} invariante={'OK' if ok else 'ROTTO'}")

